(() => {
  const page = document.querySelector('#page');
  const toast = document.querySelector('.toast');
  const nav = [...document.querySelectorAll('[data-view]')];
  const today = '5 Aug 2026';
  const btn = (text, cls = 'button') => `<button type="button" class="${cls}" data-toast="${text}">${text}</button>`;
  const pageHead = (eyebrow, title, description, action = '') => `<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</header>`;
  const lineRows = (kind) => `<div class="line-items"><table><thead><tr><th>ITEM</th><th class="num">QTY</th><th class="num">TOTAL</th><th class="num">UNIT RATE</th><th></th></tr></thead><tbody><tr><td><strong>Iron ore</strong><span class="meta">Material · 00071CF3</span></td><td class="num"><input aria-label="Iron ore quantity" value="10" inputmode="numeric"></td><td class="num"><input aria-label="Iron ore total" value="1" inputmode="numeric"></td><td class="num">0.10 <small>each</small></td><td><button class="remove" aria-label="Remove iron ore">×</button></td></tr><tr><td><strong>${kind === 'purchase' ? 'Leather' : 'Minor healing potion'}</strong><span class="meta">${kind === 'purchase' ? 'Material · 000DB5D2' : 'Potion · 0003EAF2'}</span></td><td class="num"><input aria-label="Quantity" value="4" inputmode="numeric"></td><td class="num"><input aria-label="Total" value="60" inputmode="numeric"></td><td class="num">15 <small>each</small></td><td><button class="remove" aria-label="Remove item">×</button></td></tr></tbody></table></div>`;
  const purchase = () => `<section class="view">${pageHead('RECORD · WHITERUN GENERAL', 'Store pays', 'Record goods the store has acquired. Stock becomes provisional until a verified clerk approves.', btn('Save draft', 'button secondary'))}<div class="grid two"><form class="card"> <div class="card-head"><div><h2>Purchase receipt</h2><p class="subtle">${today} · New entry</p></div><span class="status pending">Pending approval</span></div><div class="form-grid"><div><label for="supplier">Seller or organization</label><input id="supplier" placeholder="e.g. Aela the Huntress" value="Riverwood traders" /></div><div><label for="occurred">Occurred at</label><input id="occurred" type="datetime-local" value="2026-08-05T14:30" /></div><div class="wide"><label for="notes">Ledger note <small>(optional)</small></label><textarea id="notes" placeholder="Trade terms, bundle detail, or provenance">Wagon delivery from Riverwood. Iron ore is a 10-for-1 bundle.</textarea></div></div>${lineRows('purchase')}<p><button class="link-button" type="button" data-toast="Item search opened">+ Add another item</button></p><div class="receipt-total"><span class="subtle">Amounts are whole septims; unit rates are derived.</span><strong>Store pays 61 ⟡</strong></div><div class="form-actions">${btn('Discard', 'button secondary')}<div>${btn('Submit for approval')}</div></div></form><aside class="stack"><div class="card"><h3>Before you submit</h3><ul class="checklist"><li>10 iron ore adds to provisional stock.</li><li>Rates won’t affect margin or alliance data yet.</li><li>A verified colleague must review this receipt.</li></ul></div><div class="info-box"><strong>Stock guardrail</strong><br>Purchases may always add stock. A manager-only correction is required to make any balance negative.</div><div class="card"><h3>Official guide</h3><div class="rank"><span>Iron ore</span><em>Store pays: 0.10 each</em></div><div class="rank"><span>Leather</span><em>Store pays: 15–25 each</em></div></div></aside></div></section>`;
  const sale = () => `<section class="view">${pageHead('RECORD · WHITERUN GENERAL', 'Customer pays', 'Record goods sold from confirmed store stock. This receipt will publish immediately.', btn('Save draft', 'button secondary'))}<div class="grid two"><form class="card"><div class="card-head"><div><h2>Sale receipt</h2><p class="subtle">${today} · Verified clerk: Kaz Arvel</p></div><span class="status approved">Immediate approval</span></div><div class="form-grid"><div><label for="buyer">Customer or organization</label><input id="buyer" placeholder="Optional character or group" value="The Silver Hand" /></div><div><label for="sold-at">Occurred at</label><input id="sold-at" type="datetime-local" value="2026-08-05T15:10" /></div><div class="wide"><label for="sale-note">Ledger note <small>(optional)</small></label><textarea id="sale-note">Counter sale; potion shelf restocked after sale.</textarea></div></div>${lineRows('sale')}<p><button class="link-button" type="button" data-toast="Only confirmed stock can be added">+ Add from confirmed stock</button></p><div class="receipt-total"><span class="subtle">Sale reduces confirmed stock on approval.</span><strong>Customer pays 61 ⟡</strong></div><div class="form-actions">${btn('Discard', 'button secondary')}${btn('Record approved sale', 'button moss')}</div></form><aside class="stack"><div class="card"><h3>Stock check</h3><div class="rank"><span>Iron ore <small class="meta">after sale: 36</small></span><em class="positive">enough stock</em></div><div class="rank"><span>Minor healing potion <small class="meta">after sale: 2</small></span><em class="positive">enough stock</em></div></div><div class="info-box error"><strong>Example validation</strong><br>If a line exceeds confirmed stock, SkyStore blocks submission and tells you the available balance. Pending deliveries cannot be sold.</div><div class="card"><h3>Margin preview</h3><p class="subtle">Weighted cost for these goods: 41 ⟡</p><div class="metric"><strong class="positive">+20 ⟡</strong><span>Estimated gross profit · 32.8% gross margin</span></div></div></aside></div></section>`;
  const street = () => `<section class="view">${pageHead('MARKET INTELLIGENCE', 'Street report', 'Capture listings, direct quotes, and hearsay. Reports never alter store stock.', btn('Save as draft', 'button secondary'))}<div class="grid two"><form class="card"><div class="tabs"><button class="active">Seen listing</button><button>Direct quote</button><button>Word of mouth</button></div><div class="form-grid"><div><label>Item</label><input value="Refined moonstone" /></div><div><label>Market side</label><select><option>Customer pays (listing)</option><option>Store pays (buyer wanted)</option></select></div><div><label>Quantity</label><input value="2" inputmode="numeric" /></div><div><label>Total septims</label><input value="800" inputmode="numeric" /></div><div><label>Seen at / source</label><input value="Riften market, north stall" /></div><div><label>Observed at</label><input type="datetime-local" value="2026-08-05T12:00" /></div><div><label>Expires</label><input type="date" value="2026-08-12" /></div><div><label>Evidence quality</label><select><option>Seen listing · 0.35 signal</option><option>Direct quote · 0.35 signal</option><option>Word of mouth · 0.20 signal</option></select></div><div class="wide"><label>Note</label><textarea>Two ingots marked at 400 each. No haggling observed.</textarea></div></div><div class="form-actions">${btn('Clear', 'button secondary')}${btn('Submit report')}</div></form><aside class="stack"><div class="card"><h3>How reports work</h3><ul class="checklist"><li>They inform rates, not inventory.</li><li>Expired listings stop contributing to the range.</li><li>Source names are private to your store.</li></ul></div><div class="info-box"><strong>Low confidence example</strong><br>One report from one store is useful context, but cannot be called anonymized alliance data until three independent stores contribute.</div><div class="card empty-state"><div class="empty-icon">◌</div><h3>No active reports for wheat</h3><p>Start a report when you see a current price in the wild.</p></div></aside></div></section>`;
  const adjustment = () => `<section class="view">${pageHead('INVENTORY CONTROL · WHITERUN GENERAL', 'Stock adjustment', 'Correct a physical count without disguising the reason as a trade.', btn('View stock ledger', 'button secondary'))}<div class="grid two"><form class="card"><div class="card-head"><div><h2>Reasoned correction</h2><p class="subtle">Manager-only action · immutable after confirmation</p></div><span class="status warning">Audit required</span></div><div class="form-grid"><div><label for="adjust-item">Item</label><input id="adjust-item" value="Iron ore" /></div><div><label for="counted">Physical count</label><input id="counted" value="8" inputmode="numeric" /></div><div><label>Ledger currently shows</label><input value="6 confirmed + 4 pending" disabled /></div><div><label>Confirmed difference</label><input value="+2" disabled /></div><div class="wide"><label for="adjust-reason">Required reason</label><textarea id="adjust-reason">Shelf count after the evening shift; two loose ore pieces were stored with ingots.</textarea></div></div><div class="info-box"><strong>Pending stock is not rewritten.</strong><br>This correction adds two confirmed units. The separate pending delivery still requires approval.</div><div class="form-actions">${btn('Cancel', 'button secondary')}${btn('Record correction', 'button danger')}</div></form><aside class="stack"><div class="card"><h3>Balance preview</h3><div class="rank"><span>Confirmed before</span><em>6</em></div><div class="rank"><span>Adjustment</span><em class="positive">+2</em></div><div class="rank"><span>Confirmed after</span><em>8</em></div><div class="rank"><span>Pending unchanged</span><em>+4</em></div></div><div class="info-box error"><strong>Negative balance guard</strong><br>A correction that would make confirmed stock negative is blocked and requires review of the underlying receipts.</div></aside></div></section>`;
  const approvals = () => `<section class="view">${pageHead('STORE WORKFLOW', 'Approval queue', 'Four submissions need a second verified set of eyes.', btn('View receipt history', 'button secondary'))}<div class="grid two"><div class="card"><div class="table-wrap"><table><thead><tr><th>SUBMISSION</th><th>SUBMITTED BY</th><th>IMPACT</th><th>STATE</th><th></th></tr></thead><tbody><tr><td><strong>Purchase #WGS-2048</strong><span class="meta">Iron ore ×10, leather ×4 · 61 ⟡</span></td><td>Kara Bone-Breaker<span class="meta">8 min ago</span></td><td class="positive">+14 stock</td><td><span class="status pending">Pending</span></td><td><button class="link-button" data-review="Purchase #WGS-2048">Review</button></td></tr><tr><td><strong>Street report #R-309</strong><span class="meta">Refined moonstone · 400 each</span></td><td>Orryn<span class="meta">31 min ago</span></td><td>Market signal</td><td><span class="status pending">Pending</span></td><td><button class="link-button" data-review="Street report #R-309">Review</button></td></tr><tr><td><strong>Recipe #RC-18</strong><span class="meta">Fine clothes · labor 25 ⟡</span></td><td>Elisif’s Steward<span class="meta">Yesterday</span></td><td>Recipe cost</td><td><span class="status pending">Pending</span></td><td><button class="link-button" data-review="Recipe #RC-18">Review</button></td></tr></tbody></table></div></div><aside class="card" id="review"><div class="eyebrow">SELECTED REVIEW</div><h2>Purchase #WGS-2048</h2><p class="subtle">Submitted by Kara Bone-Breaker · Aug 5, 14:30</p><div class="info-box">This adds <strong>10 iron ore</strong> and <strong>4 leather</strong> to confirmed stock after approval. It will contribute to private alliance estimates.</div><div class="rank"><span>Iron ore ×10</span><em>1 ⟡ total</em></div><div class="rank"><span>Leather ×4</span><em>60 ⟡ total</em></div><label for="review-note">Reviewer note</label><textarea id="review-note" placeholder="Optional note for the audit ledger"></textarea><div class="actions" style="margin-top:14px">${btn('Approve', 'button moss')}${btn('Reject', 'button danger')}</div><p class="subtle">You cannot approve your own submission. Decisions are immutable; approved receipts may later be voided with a correction.</p></aside></div></section>`;
  const reports = () => `<section class="view">${pageHead('STORE INTELLIGENCE', 'Trading reports', 'Confirmed activity only · 1 Jul – 5 Aug 2026', btn('Export CSV', 'button secondary'))}<div class="tabs"><button class="active">Sales & margin</button><button>Stock velocity</button><button>Hot & slow</button></div><div class="report-grid"><div class="card metric"><strong>3,840 ⟡</strong><span>Confirmed sales</span></div><div class="card metric"><strong class="positive">1,202 ⟡</strong><span>Gross profit · 31.3%</span></div><div class="card metric"><strong>38</strong><span>Items sold · 17 lines</span></div><div class="card metric"><strong class="negative">6</strong><span>Low-stock alerts</span></div></div><div class="grid two"><div class="card"><div class="card-head"><div><h2>Sales and margin</h2><p class="subtle">Daily confirmed sales in septims</p></div><span class="pill">Last 35 days</span></div><div class="chart" aria-label="Illustrative sales trend chart"></div></div><div class="card"><h2>Best margin contributors</h2><div class="rank"><strong>1</strong><span>Minor healing potion<small class="meta">12 sold · 14 ⟡ average</small></span><em class="positive">+242 ⟡</em></div><div class="rank"><strong>2</strong><span>Fine clothes<small class="meta">3 sold · 190 ⟡ average</small></span><em class="positive">+170 ⟡</em></div><div class="rank"><strong>3</strong><span>Refined moonstone<small class="meta">4 sold · 460 ⟡ average</small></span><em class="positive">+152 ⟡</em></div></div></div><div class="grid two" style="margin-top:18px"><div class="card"><h2>Stock velocity</h2><p class="subtle">Confirmed units sold / average units held</p><div class="rank"><span>Wheat <div class="bar"><i style="width:88%"></i></div></span><em>2.4× / 30d</em></div><div class="rank"><span>Iron ore <div class="bar"><i style="width:63%"></i></div></span><em>1.1× / 30d</em></div><div class="rank"><span>Leather <div class="bar"><i style="width:30%"></i></div></span><em>0.4× / 30d</em></div></div><div class="card"><h2>Hot and slow items</h2><div class="split-list"><div><span class="status healthy">Hot</span><div class="rank"><span>Minor healing potion</span><em>sold today</em></div><div class="rank"><span>Wheat</span><em>sold 1d ago</em></div></div><div><span class="status low">Slow</span><div class="rank"><span>Fine clothes</span><em>last trade 19d</em></div><div class="rank"><span>Saber cat pelt</span><em>last trade 33d</em></div></div></div></div></div></section>`;
  const store = () => `<section class="view">${pageHead('WHITERUN GENERAL', 'Store administration', 'Members, trust, alliance agreement, and pricing controls.', btn('Invite staff'))}<div class="tabs"><button class="active">Staff & trust</button><button>Pricing targets</button><button>Agreement</button><button>Stock controls</button></div><div class="grid two"><div class="card"><div class="card-head"><div><h2>Store staff</h2><p class="subtle">Trust is limited to this store.</p></div><span class="pill">4 members</span></div><div class="table-wrap"><table><thead><tr><th>MEMBER</th><th>ROLE</th><th>TRUST</th><th></th></tr></thead><tbody><tr><td><div class="member"><span class="avatar dark">KA</span>Kaz Arvel</div></td><td>Owner</td><td><span class="status approved">Verified</span></td><td><button class="link-button">Manage</button></td></tr><tr><td><div class="member"><span class="avatar">KB</span>Kara Bone-Breaker</div></td><td>Clerk</td><td><span class="status pending">Unverified</span></td><td><button class="link-button">Verify</button></td></tr><tr><td><div class="member"><span class="avatar dark">OR</span>Orryn</div></td><td>Manager</td><td><span class="status approved">Verified</span></td><td><button class="link-button">Manage</button></td></tr></tbody></table></div></div><div class="card"><h2>Pricing targets</h2><p class="subtle">Markup on cost is your primary store rule.</p><div class="form-grid"><div><label>Default target markup</label><input value="35" /><small>% over effective cost</small></div><div><label>Low stock threshold</label><input value="5" /><small>units per item</small></div><div class="wide"><label>Sale floor behavior</label><select><option>Use effective cost × 1.35</option></select></div></div><p class="info-box">For recipe-backed goods, the recommended maximum purchase is also capped by verified craft replacement cost.</p>${btn('Save pricing targets')}</div></div><div class="card" style="margin-top:18px"><div class="card-head"><div><h2>Alliance information-sharing agreement</h2><p class="subtle">Version 1.2 accepted by Kaz Arvel on 1 Aug 2026.</p></div><span class="status approved">Active</span></div><p>Approved rates may contribute anonymously to the shared alliance market. Raw stock, receipts, counterparties, and staff identities stay inside Whiterun General.</p><button class="link-button">Read accepted agreement</button></div></section>`;
  const platform = () => `<section class="view">${pageHead('PLATFORM ADMINISTRATION', 'Alliance control room', 'Private platform tools — all actions are recorded in the immutable audit ledger.', btn('Create store'))}<div class="tabs"><button class="active">Stores</button><button>Users</button><button>Audit log</button><button>Quarantine</button></div><div class="grid two"><div class="card"><h2>Stores</h2><div class="table-wrap"><table><thead><tr><th>STORE</th><th>MEMBERS</th><th>STATUS</th><th></th></tr></thead><tbody><tr><td><strong>Whiterun General</strong><span class="meta">Active since Aug 1</span></td><td>4</td><td><span class="status approved">Active</span></td><td><button class="link-button">Inspect</button></td></tr><tr><td><strong>Riften Outfitters</strong><span class="meta">Agreement pending</span></td><td>2</td><td><span class="status pending">Pending</span></td><td><button class="link-button">Inspect</button></td></tr><tr><td><strong>Solitude Fine Goods</strong><span class="meta">Signal review required</span></td><td>7</td><td><span class="status warning">Flagged</span></td><td><button class="link-button">Inspect</button></td></tr></tbody></table></div></div><div class="card"><h2>Quarantine contributor</h2><p class="subtle">Suspends access, rejects their pending entries, and removes their market signals. Confirmed stock remains until a fraudulent receipt is voided.</p><label>Discord identity or user</label><input value="BanditMerchant#4521" /><label style="margin-top:12px">Reason</label><textarea>Repeated unverifiable listing reports.</textarea>${btn('Quarantine and recompute', 'button danger')}<p class="subtle">Requires platform-admin confirmation.</p></div></div><div class="card" style="margin-top:18px"><div class="card-head"><div><h2>Recent immutable audit entries</h2><p class="subtle">UTC timestamps · hashes truncated for display</p></div><button class="link-button">Open full audit log</button></div><div class="table-wrap"><table class="audit"><thead><tr><th>TIME</th><th>ACTOR</th><th>EVENT</th><th>CORRELATION</th></tr></thead><tbody><tr><td>2026-08-05 06:30:01</td><td>admin:118204</td><td>catalog.version.activated v2026.08.05</td><td>3c1e…9d4f</td></tr><tr><td>2026-08-05 06:10:15</td><td>store:whiterun</td><td>receipt.approved WGS-2041</td><td>7ab3…5ff1</td></tr><tr><td>2026-08-04 23:00:00</td><td>worker:snapshot</td><td>public_snapshot.created 2026-07-28 cutoff</td><td>110e…c20b</td></tr></tbody></table></div></div></section>`;
  const catalog = () => `<section class="view">${pageHead('CATALOG ADMINISTRATION', 'Catalog intake', 'Review a versioned import, add manual goods, and resolve references without rewriting history.', btn('New custom item'))}<div class="tabs"><button class="active">Import preview</button><button>Custom item</button><button>Unresolved mapping</button></div><div class="grid two"><div class="card"><h2>Keizaal catalog import</h2><p class="subtle">Version 2026.08.05 · staged by offline builder</p><div class="import-drop"><strong>keizaal-v2026.08.05.catalog.json</strong><br><small>22,418 inventory-capable records · 100% artwork fallback coverage</small><p>${btn('Review staged import')}</p></div><div class="rank"><span>New items</span><em>184</em></div><div class="rank"><span>Changed winning overrides</span><em>26</em></div><div class="rank"><span>Retirements with history</span><em>3 · retained</em></div></div><div class="card"><h2>Create custom item</h2><div class="form-grid"><div><label>Name</label><input placeholder="e.g. Merchant's travel cloak" /></div><div><label>Commerce category</label><select><option>Clothing</option><option>Material</option><option>Miscellaneous</option></select></div><div class="wide"><label>Original icon</label><input type="file" accept="image/*" /></div><div class="wide"><label>Aliases</label><input placeholder="travel cloak, merchant cloak" /></div></div><p class="info-box">Manual items require a name, category, and icon. Their identity is stable even if later merged.</p>${btn('Create unpublished item')}</div></div><div class="card" style="margin-top:18px"><div class="card-head"><div><h2>Unresolved item mappings</h2><p class="subtle">These drafts remain out of published price guides until resolved.</p></div><span class="status warning">3 require attention</span></div><div class="mapping"><div><strong>“wolf skin”</strong><span class="meta">Whiterun price sheet · 12 ⟡</span></div><span>→</span><select><option>Select canonical catalog item…</option><option>Wolf pelt · 0003AD74</option><option>Wolf hide · custom item</option></select></div><div class="mapping"><div><strong>“moonstone bar”</strong><span class="meta">Riften screenshot · 400 ⟡</span></div><span>→</span><select><option>Refined moonstone · 0005AD9F</option></select></div><div class="mapping"><div><strong>“fine clothing set”</strong><span class="meta">Street report #R-289 · 550 ⟡</span></div><span>→</span><select><option>Select canonical catalog item…</option><option>Fine clothes · 0008698B</option></select></div><div class="form-actions" style="margin-top:16px">${btn('Keep as unpublished draft', 'button secondary')}${btn('Apply selected mappings')}</div></div></section>`;
  const views = {purchase, sale, street, adjustment, approvals, reports, store, platform, catalog};
  function render(){ const requested = location.hash.slice(1) || 'purchase'; const name = views[requested] ? requested : 'purchase'; page.innerHTML = views[name](); nav.forEach(a=>a.classList.toggle('active',a.dataset.view===name)); const mobileRoute = document.querySelector('#mobile-route'); if (mobileRoute) mobileRoute.value = `#${name}`; document.title = `SkyStore — ${name[0].toUpperCase()+name.slice(1)}`; }
  function note(message){ toast.textContent = message; toast.classList.add('show'); clearTimeout(note.t); note.t = setTimeout(()=>toast.classList.remove('show'),2400); }
  document.querySelector('#mobile-route')?.addEventListener('change', event => { const target = event.target.value; if (target.startsWith('#')) location.hash = target; else location.href = target; });
  window.addEventListener('hashchange',render); document.addEventListener('click',e=>{const action=e.target.closest('[data-toast]'); if(action)note(`${action.dataset.toast} — prototype action`); const review=e.target.closest('[data-review]'); if(review){note(`Opened ${review.dataset.review}`); document.querySelector('#review')?.scrollIntoView({behavior:'smooth'});}}); document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search').focus();}}); render();
})();
